-- the body id for a gender and a fitness build
function D.id(gender, build)
	gender = (gender == "Female") and "Female" or "Male"
	build = D.BUILD_ALIAS[build] or build
	local id = gender .. "_" .. tostring(build)
	return D.bodies[id] and id or (gender .. "_Average")
end
return D
